    for (int i = 0; i < count; i++) {
        // Simulate push by reallocating and adding value
        if (vec->contents == NULL) {
            vec->contents = (int*)malloc(sizeof(int) * (vec->len + 1));
        } else {
            vec->contents = (int*)realloc(vec->contents, sizeof(int) * (vec->len + 1));
        }

        if (vec->contents == NULL) {
            return -1;
